const items = $input.all().map(i => i.json);

// Loc cap USDT, bo stablecoin va leveraged token (khong phai tai san thuong)
const EXCLUDE = ['USDCUSDT','FDUSDUSDT','BUSDUSDT','TUSDUSDT','DAIUSDT','USDPUSDT','EURUSDT','USD1USDT'];
const filtered = items.filter(t => {
  if (!t.symbol || !t.symbol.endsWith('USDT')) return false;
  if (EXCLUDE.includes(t.symbol)) return false;
  if (/UP USDT|DOWN USDT/.test(t.symbol)) return false;
  if (t.symbol.includes('UPUSDT') || t.symbol.includes('DOWNUSDT') || t.symbol.includes('BULLUSDT') || t.symbol.includes('BEARUSDT')) return false;
  return true;
});

filtered.sort((a, b) => parseFloat(b.quoteVolume) - parseFloat(a.quoteVolume));
const top50 = filtered.slice(0, 50).map(t => ({ symbol: t.symbol }));

return top50.map(t => ({ json: t }));

const symbol = $('Loop Over Items').first().json.symbol;
const candlesRaw = $input.all().map(i => i.json);

if (!Array.isArray(candlesRaw) || candlesRaw.length < 25 || !Array.isArray(candlesRaw[0])) {
  return [{ json: { symbol, score: 0, candles_since_cross: null, cross_direction: null, atr_pct: 0, trend_pct: 0, volume_ratio: 0 } }];
}

const candles = candlesRaw.map(k => ({
  time: k[0], open: parseFloat(k[1]), high: parseFloat(k[2]),
  low: parseFloat(k[3]), close: parseFloat(k[4]), volume: parseFloat(k[5])
}));

function ema(values, period) {
  const k = 2 / (period + 1);
  const out = [];
  let prev = null;
  for (let i = 0; i < values.length; i++) {
    if (i < period - 1) { out.push(null); continue; }
    if (prev === null) {
      const seed = values.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0) / period;
      prev = seed; out.push(seed); continue;
    }
    prev = values[i] * k + prev * (1 - k);
    out.push(prev);
  }
  return out;
}

function atr(cs, period) {
  const trs = [];
  for (let i = 0; i < cs.length; i++) {
    if (i === 0) { trs.push(cs[i].high - cs[i].low); continue; }
    const pc = cs[i - 1].close;
    trs.push(Math.max(cs[i].high - cs[i].low, Math.abs(cs[i].high - pc), Math.abs(cs[i].low - pc)));
  }
  const out = [];
  for (let i = 0; i < trs.length; i++) {
    if (i < period - 1) { out.push(null); continue; }
    out.push(trs.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0) / period);
  }
  return out;
}

const closes = candles.map(c => c.close);
const ema9 = ema(closes, 9);
const ema21 = ema(closes, 21);
const atr14 = atr(candles, 14);

const n = candles.length;
const lookback = Math.min(15, n - 22);
let candlesSinceCross = null;
let crossDirection = null;

for (let back = 0; back < lookback; back++) {
  const i = n - 1 - back;
  if (i < 1 || ema9[i] === null || ema21[i] === null || ema9[i - 1] === null || ema21[i - 1] === null) continue;
  const crossUp = ema9[i - 1] <= ema21[i - 1] && ema9[i] > ema21[i];
  const crossDown = ema9[i - 1] >= ema21[i - 1] && ema9[i] < ema21[i];
  if (crossUp || crossDown) {
    candlesSinceCross = back;
    crossDirection = crossUp ? 'BUY' : 'SELL';
    break;
  }
}

const lastIdx = n - 1;
const trendLookback = Math.min(20, n - 1);
const trendPct = ((closes[lastIdx] - closes[lastIdx - trendLookback]) / closes[lastIdx - trendLookback]) * 100;

const lastATR = atr14[lastIdx] || 0;
const atrPct = lastATR > 0 ? (lastATR / closes[lastIdx]) * 100 : 0;

const volLookback = Math.min(20, n - 2);
const avgVolume = candles.slice(lastIdx - volLookback, lastIdx).reduce((a, c) => a + c.volume, 0) / volLookback;
const volumeRatio = avgVolume > 0 ? (candles[lastIdx].volume / avgVolume) : 0;

let crossScore = 0;
if (candlesSinceCross !== null) crossScore = Math.max(0, (6 - candlesSinceCross)) / 6 * 40;

const trendScore = Math.min(Math.abs(trendPct) / 8, 1) * 30;

let atrScore = 0;
if (atrPct >= 1 && atrPct <= 6) atrScore = 15;
else if (atrPct > 0) atrScore = Math.max(0, 15 - Math.abs(atrPct - 3.5) * 3);

const volumeScore = Math.min(volumeRatio, 2) / 2 * 15;

const totalScore = crossScore + trendScore + atrScore + volumeScore;

return [{ json: {
  symbol,
  score: Math.round(totalScore * 100) / 100,
  candles_since_cross: candlesSinceCross,
  cross_direction: crossDirection,
  atr_pct: Math.round(atrPct * 100) / 100,
  trend_pct: Math.round(trendPct * 100) / 100,
  volume_ratio: Math.round(volumeRatio * 100) / 100
} }];
